// Express middleware: make POST /payments idempotent
async function idempotency(req, res, next) {
  const key = req.header('Idempotency-Key');
  if (!key) return res.status(400).json({ error: 'Idempotency-Key required' });

  const cached = await store.get(key); // e.g. Redis
  if (cached) {
    // Replay the original response, do NOT re-charge
    return res.status(cached.status).json(cached.body);
  }

  // Reserve the key so concurrent retries don't both execute
  const reserved = await store.setNX(key, { pending: true }, { ttl: 86400 });
  if (!reserved) return res.status(409).json({ error: 'Request in progress' });

  // Capture the response to persist it
  const json = res.json.bind(res);
  res.json = (body) => {
    store.set(key, { status: res.statusCode, body }, { ttl: 86400 });
    return json(body);
  };
  next();
}

