async function authGuard(req, res, next) {
  const header = req.header('Authorization') || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Missing token' });

  try {
    const claims = jwt.verify(token, process.env.JWT_SECRET);
    // Revocation check: denylist holds jti of revoked tokens until expiry
    if (await denylist.has(claims.jti)) {
      return res.status(401).json({ error: 'Token revoked' });
    }
    req.user = claims;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

const ALLOWED = new Set(['https://app.example.com']);

app.use((req, res, next) => {
  const origin = req.header('Origin');
  if (origin && ALLOWED.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin); // not '*' with creds
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }

  if (req.method === 'OPTIONS') {
    // Preflight response
    res.setHeader('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, X-Api-Version, Authorization');
    res.setHeader('Access-Control-Max-Age', '600'); // cache 10 min
    return res.status(204).end();
  }
  next();
});

import crypto from 'crypto';
const etagOf = (doc) => '"' + crypto.createHash('sha1').update(JSON.stringify(doc)).digest('hex') + '"';

app.get('/articles/:id', async (req, res) => {
  const doc = await db.articles.get(req.params.id);
  if (!doc) return res.sendStatus(404);
  const etag = etagOf(doc);
  res.setHeader('ETag', etag);
  res.setHeader('Cache-Control', 'private, max-age=60');

  if (req.header('If-None-Match') === etag) {
    return res.status(304).end(); // unchanged, no body
  }
  res.json(doc);
});

app.put('/articles/:id', async (req, res) => {
  const doc = await db.articles.get(req.params.id);
  if (!doc) return res.sendStatus(404);

  if (req.header('If-Match') !== etagOf(doc)) {
    return res.status(412).json({ error: 'Resource changed; refetch and retry' });
  }
  const updated = await db.articles.update(req.params.id, req.body);
  res.setHeader('ETag', etagOf(updated));
  res.json(updated);
});

app.get('/feed', async (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);
  const cursor = req.query.cursor
    ? JSON.parse(Buffer.from(req.query.cursor, 'base64').toString())
    : null;

  // Stable keyset: order by (created_at, id) and seek past the cursor
  const rows = await db.query(
    `SELECT id, created_at, body FROM posts
     ${cursor ? 'WHERE (created_at, id) < ($1, $2)' : ''}
     ORDER BY created_at DESC, id DESC
     LIMIT $${cursor ? 3 : 1}`,
    cursor ? [cursor.created_at, cursor.id, limit + 1] : [limit + 1]
  );

  const hasMore = rows.length > limit;
  const page = rows.slice(0, limit);
  const last = page[page.length - 1];
  const nextCursor = hasMore
    ? Buffer.from(JSON.stringify({ created_at: last.created_at, id: last.id })).toString('base64')
    : null;

  res.json({ data: page, nextCursor });
});

// Token-bucket limiter keyed per client (e.g. API key)
const CAPACITY = 10;        // max burst
const REFILL_PER_SEC = 5;   // sustained rate
const buckets = new Map();

function rateLimit(req, res, next) {
  const id = req.header('X-Api-Key') || req.ip;
  const now = Date.now() / 1000;
  const b = buckets.get(id) || { tokens: CAPACITY, ts: now };

  b.tokens = Math.min(CAPACITY, b.tokens + (now - b.ts) * REFILL_PER_SEC);
  b.ts = now;

  res.setHeader('RateLimit-Limit', CAPACITY);
  if (b.tokens < 1) {
    const wait = Math.ceil((1 - b.tokens) / REFILL_PER_SEC);
    res.setHeader('Retry-After', wait);
    res.setHeader('RateLimit-Remaining', 0);
    buckets.set(id, b);
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }

  b.tokens -= 1;
  res.setHeader('RateLimit-Remaining', Math.floor(b.tokens));
  buckets.set(id, b);
  next();
}

