// Verify on state-changing requests (double-submit)
function csrfGuard(req, res, next) {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  const cookieToken = req.cookies.csrf;
  const headerToken = req.header('X-CSRF-Token');
  if (!cookieToken || cookieToken !== headerToken) {
    return res.status(403).json({ error: 'CSRF validation failed' });
  }
  next();
}

app.get('/reports/:id', async (req, res) => {
  const rows = await db.reports.rows(req.params.id);
  res.setHeader('Vary', 'Accept'); // caches must key on Accept

  // express req.accepts() returns the best match or false
  switch (req.accepts(['json', 'csv'])) {
    case 'json':
      return res.type('application/json').json(rows);
    case 'csv': {
      const header = Object.keys(rows[0] || {}).join(',');
      const body = rows.map(r => Object.values(r).join(',')).join('\n');
      return res.type('text/csv').send(header + '\n' + body);
    }
    default:
      return res.status(406).json({ error: 'Supported: application/json, text/csv' });
  }
});

