// IMPORTANT: verify against the RAW body, before JSON parsing
app.post('/webhooks/stripe', express.raw({ type: '*/*' }), async (req, res) => {
  const sig = req.header('X-Signature');
  const ts = Number(req.header('X-Timestamp'));

  // 1. Reject replays
  if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) {
    return res.status(400).send('Stale timestamp');
  }

  // 2. Verify HMAC signature (timing-safe)
  const expected = crypto
    .createHmac('sha256', process.env.WEBHOOK_SECRET)
    .update(`${ts}.` + req.body) // raw Buffer
    .digest('hex');
  if (!sig || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
    return res.status(401).send('Bad signature');
  }

  const event = JSON.parse(req.body.toString());

  // 3. Dedupe redeliveries, ack fast, process async
  if (!(await seen.add(event.id))) return res.status(200).send('Duplicate ignored');
  await queue.enqueue(event);
  res.status(200).send('ok');
});

